def to_year_numbers(apps, schema_editor):
    """Staff numbers change from PB-001 to the year started + number (26001). The order stays the same.
    Short plain numbers someone typed (like 001) get the next free number for their year."""
    Settings = apps.get_model("staff", "PayrollSettings")
    Employee = apps.get_model("staff", "Employee")
    for s in Settings.objects.all():
        s.staff_no_style = "year"
        if s.staff_no_prefix.strip().upper() in ("PB-", "PB"):
            s.staff_no_prefix = ""
        s.save()
    taken = {c.strip().upper() for c in Employee.objects.values_list("code", flat=True) if c.strip()}
    pb = re.compile(r"^PB-?\s*(\d+)$", re.I)
    for e in Employee.objects.order_by("pk"):
        m = pb.match(e.code.strip())
        if not m:
            continue
        new = f"{e.start_date.year % 100:02d}{int(m.group(1)):03d}"
        if new in taken:
            continue
        taken.discard(e.code.strip().upper())
        taken.add(new)
        e.code = new
        e.save(update_fields=["code"])
    for e in Employee.objects.order_by("start_date", "pk"):
        c = e.code.strip()
        if not (c.isdigit() and len(c) <= 3):
            continue
        yy = f"{e.start_date.year % 100:02d}"
        top = max([int(t[2:]) for t in taken if t.isdigit() and len(t) >= 5 and t.startswith(yy)], default=0)
        new = f"{yy}{top + 1:03d}"
        taken.discard(c.upper())
        taken.add(new)
        e.code = new
        e.save(update_fields=["code"])


